import { readdir } from "node:fs/promises";
import { randomBytes, randomUUID } from "node:crypto";
import { spawn } from "node:child_process";
import { requireTestDatabaseUrl } from "../tests/helpers/foundation-db";

// Never connect to an inherited DATABASE_URL. Every run owns a fresh project,
// loopback-only random port, password and tmpfs; cleanup names only that project.
const project = `mailloop-usage-${randomUUID()}`;
const env = { ...process.env, MAILLOOP_TEST_PASSWORD: randomUUID() };
const compose = [
  "compose",
  "--project-name",
  project,
  "--file",
  "docker-compose.test.yml",
];
function run(
  command: string,
  args: string[],
  commandEnv: NodeJS.ProcessEnv = env,
  capture = false,
): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      env: commandEnv,
      stdio: capture ? ["ignore", "pipe", "inherit"] : "inherit",
    });
    let output = "";
    child.stdout?.on("data", (data) => {
      output += data.toString();
    });
    child.on("error", reject);
    child.on("exit", (code, signal) =>
      code === 0
        ? resolve(output.trim())
        : reject(new Error(`${command} exited ${code ?? signal}`)),
    );
  });
}
async function main() {
  let interrupted = false;
  const onSignal = () => {
    interrupted = true;
    process.exitCode = 1;
  };
  process.on("SIGINT", onSignal);
  process.on("SIGTERM", onSignal);
  try {
    await run("docker", [
      ...compose,
      "up",
      "--detach",
      "--wait",
      "--wait-timeout",
      "45",
    ]);
    const port = await run(
      "docker",
      [...compose, "port", "postgres", "5432"],
      env,
      true,
    );
    if (!/^127\.0\.0\.1:\d+$/.test(port))
      throw new Error("Expected one disposable loopback binding.");
    const databaseUrl = `postgresql://mailloop_test:${env.MAILLOOP_TEST_PASSWORD}@${port}/mailloop_usage_test`;
    requireTestDatabaseUrl(databaseUrl);
    const adminUrl = new URL(databaseUrl);
    adminUrl.username = "mailloop_admin_test";
    adminUrl.password = randomBytes(32).toString("hex");
    const testEnv = {
      ...env,
      TZ: "UTC",
      ADMIN_DATABASE_URL: adminUrl.toString(),
      DATABASE_URL: databaseUrl,
      MAILLOOP_DB_TESTS: "1",
      TOKEN_ENCRYPTION_ACTIVE_KEY_ID: "fixture",
      TOKEN_ENCRYPTION_ACTIVE_KEY: randomBytes(32).toString("hex"),
      TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON: "{}",
      DELETION_TOMBSTONE_HMAC_KEY: randomBytes(32).toString("hex"),
    };
    if (interrupted) throw new Error("Test run interrupted.");
    await run("npm", ["run", "db:deploy"], testEnv);
    await run(
      "npm",
      ["exec", "--", "tsx", "scripts/provision-admin-db.ts"],
      testEnv,
    );
    if (
      process.argv.includes("--billing-only") ||
      process.argv.includes("--billing-pages")
    ) {
      await run(
        "npm",
        [
          "exec",
          "--",
          "vitest",
          "run",
          ...(await readdir("tests"))
            .filter(
              (name) =>
                (name.startsWith("dodo-") ||
                  (process.argv.includes("--billing-pages") &&
                    [
                      "maintenance.db.test.ts",
                      "launch.db.test.ts",
                      "usage-reporting.db.test.ts",
                    ].includes(name))) &&
                name.endsWith(".db.test.ts"),
            )
            .sort()
            .map((name) => `tests/${name}`),
          "--fileParallelism=false",
        ],
        testEnv,
      );
    } else if (!process.argv.includes("--e2e-only")) {
      await run(
        "npm",
        [
          "exec",
          "--",
          "vitest",
          "run",
          ...(await readdir("tests"))
            .filter(
              (name) =>
                name.startsWith("usage-") && name.endsWith(".db.test.ts"),
            )
            .sort()
            .map((name) => `tests/${name}`),
          "--fileParallelism=false",
        ],
        testEnv,
      );
      if (interrupted) throw new Error("Test run interrupted.");
      await run(
        "npm",
        ["run", "test:db", "--", "--fileParallelism=false"],
        testEnv,
      );
      await run("npm", ["run", "usage:backfill", "--", "--dry-run"], testEnv);
    }
    if (
      process.argv.includes("--e2e") ||
      process.argv.includes("--e2e-only") ||
      process.argv.includes("--billing-pages")
    ) {
      if (process.env.MAILLOOP_E2E_BASE_URL)
        throw new Error(
          "Disposable browser tests must start their own server.",
        );
      await run(
        "npm",
        [
          "exec",
          "--",
          "playwright",
          "test",
          ...process.argv.filter(
            (arg) =>
              arg.startsWith("--grep=") ||
              arg.startsWith("--grep-invert=") ||
              arg.startsWith("--project=") ||
              arg.startsWith("--reporter=") ||
              arg.startsWith("--output=") ||
              arg.startsWith("--config="),
          ),
          ...(process.argv.includes("--update-snapshots")
            ? ["--update-snapshots=all"]
            : []),
          ...(process.argv
            .find((arg) => arg.startsWith("--browser="))
            ?.slice("--browser=".length)
            .split(",") ?? [
            ...(process.argv.includes("--billing-pages")
              ? ["dodo-billing", "pricing", "policies"]
              : ["feature-gates", "app.spec", "landing", "policies"]),
          ]),
        ],
        {
          ...testEnv,
          MAILLOOP_E2E_ISOLATED: "1",
          // Browser verification must never inherit real payment credentials.
          DODO_PAYMENTS_ENVIRONMENT: "test_mode",
          DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
          DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_browser_fixture",
          DODO_PAYMENTS_BUSINESS_ID: "bus_browser_fixture",
          DODO_PAYMENTS_WEBHOOK_KEY:
            "whsec_" + randomBytes(32).toString("base64"),
          DODO_PAYMENTS_BASE_URL: "",
          DODO_PAYMENTS_CUSTOM_HEADERS: "",
          APP_ORIGIN: "http://localhost:3100",
          AUTH_SECRET: randomUUID(),
          TOKEN_ENCRYPTION_KEY:
            randomUUID().replaceAll("-", "") + randomUUID().replaceAll("-", ""),
        },
      );
    }
  } catch (error) {
    console.error(
      error instanceof Error
        ? error.message
        : "Disposable database tests failed.",
    );
    process.exitCode = 1;
  } finally {
    await run("docker", [
      ...compose,
      "down",
      "--volumes",
      "--remove-orphans",
    ]).catch(() => {
      process.exitCode = 1;
    });
    process.off("SIGINT", onSignal);
    process.off("SIGTERM", onSignal);
  }
}
void main();
